#!/usr/bin/env bash
# Run the judge selected by task.toml. Generated by scripts/rewrite_harbor_task_test_sh.py.
set -euo pipefail

# The worker Python requires the image's newer libstdc++ from Nix.
LIBSTDC_PATH=$(find /nix/store -maxdepth 4 -name libstdc++.so.6 -not -path '*/man/*' 2>/dev/null | head -1 || true)
if [ -n "$LIBSTDC_PATH" ]; then
    export LD_LIBRARY_PATH="$(dirname "$LIBSTDC_PATH")${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
fi

# Prefer the worker venv: it holds the nexus code of the *current* run, so a judge
# change takes effect without rebuilding the image. Fall back to the nexus shipped
# in the runtime image when runtime_configs.main.worker_venv is off.
shopt -s nullglob
VENV_PYTHONS=(/tmp/nexus/runtime/venvs/*/bin/python)
shopt -u nullglob

JUDGE_PYTHON=""
if [ "${#VENV_PYTHONS[@]}" -gt 1 ]; then
    # Never guess which venv holds the judge code: a wrong pick scores silently.
    printf 'ambiguous worker venvs, refusing to guess which holds the judge code:\n' >&2
    printf '  %s\n' "${VENV_PYTHONS[@]}" >&2
    exit 1
elif [ "${#VENV_PYTHONS[@]}" -eq 1 ]; then
    JUDGE_PYTHON="${VENV_PYTHONS[0]}"
elif [ -x "/nix/runtime/nexus/.venv-3.13/bin/python" ]; then
    JUDGE_PYTHON="/nix/runtime/nexus/.venv-3.13/bin/python"
else
    echo "no judge python found; looked for:" >&2
    echo "  /tmp/nexus/runtime/venvs/*/bin/python  (set runtime_configs.main.worker_venv=true)" >&2
    echo "  /nix/runtime/nexus/.venv-3.13/bin/python  (shipped in the runtime image)" >&2
    exit 1
fi

# Logged so the verifier output says which nexus actually graded this rollout.
echo "judge python: $JUDGE_PYTHON" >&2

exec "$JUDGE_PYTHON" -m nexus.extensions.tasks.artifact.harbor_entry
